-- -------------------------------------------------------------------------
-- 1. NGUOI DUNG (TAC GIA BAI BAO LICH SU)
-- -------------------------------------------------------------------------
IF OBJECT_ID('tempdb..#TmpNguoiDung') IS NOT NULL DROP TABLE #TmpNguoiDung;
CREATE TABLE #TmpNguoiDung (
  [MaNguoiDung] INT,
  [TenDangNhap] NVARCHAR(MAX),
  [HoDem] NVARCHAR(MAX),
  [Ten] NVARCHAR(MAX),
  [HoTen] NVARCHAR(MAX),
  [Email] NVARCHAR(MAX),
  [MatKhau] NVARCHAR(MAX),
  [HocVi] NVARCHAR(MAX),
  [HocHam] NVARCHAR(MAX),
  [GioiTinh] NVARCHAR(MAX),
  [NgonNgu] NVARCHAR(MAX),
  [QuocGia] NVARCHAR(MAX),
  [SoDienThoai] NVARCHAR(MAX),
  [DonVi] NVARCHAR(MAX),
  [DiaChi] NVARCHAR(MAX),
  [SoTaiKhoan] NVARCHAR(MAX),
  [ChuTaiKhoan] NVARCHAR(MAX),
  [NganHang] NVARCHAR(MAX),
  [MaORCID] NVARCHAR(MAX),
  [TrangThai] BIT,
  [NgayTao] DATETIME,
  [AnhDaiDien] NVARCHAR(MAX)
);

SET IDENTITY_INSERT NguoiDung ON;
SELECT [MaNguoiDung], [TenDangNhap], [HoDem], [Ten], [HoTen], [Email], [MatKhau], [HocVi], [HocHam], [GioiTinh], [NgonNgu], [QuocGia], [SoDienThoai], [DonVi], [DiaChi], [SoTaiKhoan], [ChuTaiKhoan], [NganHang], [MaORCID], [TrangThai], [NgayTao], [AnhDaiDien] FROM #TmpNguoiDung t
WHERE NOT EXISTS (SELECT 1 FROM NguoiDung n WHERE n.MaNguoiDung = t.MaNguoiDung);
SET IDENTITY_INSERT NguoiDung OFF;
DROP TABLE #TmpNguoiDung;
PRINT N'  [OK] Da dong bo ' + CAST(@@ROWCOUNT AS NVARCHAR(10)) + N' tai khoan nguoi dung lich su.';
GO

