-- -------------------------------------------------------------------------
-- 4. SO TAP CHI (23 SO PHAT HANH 2016 - 2026)
-- -------------------------------------------------------------------------
IF OBJECT_ID('tempdb..#TmpSoTapChi') IS NOT NULL DROP TABLE #TmpSoTapChi;
CREATE TABLE #TmpSoTapChi (
  [MaSoTapChi] INT,
  [TenSo] NVARCHAR(500),
  [Tap] INT,
  [So] INT,
  [Nam] INT,
  [NgayPhatHanh] DATETIME,
  [TrangThai] NVARCHAR(500)
);

SET IDENTITY_INSERT SoTapChi ON;
SELECT [MaSoTapChi], [TenSo], [Tap], [So], [Nam], [NgayPhatHanh], [TrangThai] FROM #TmpSoTapChi t
WHERE NOT EXISTS (SELECT 1 FROM SoTapChi s WHERE s.MaSoTapChi = t.MaSoTapChi);
SET IDENTITY_INSERT SoTapChi OFF;
DROP TABLE #TmpSoTapChi;
PRINT N'  [OK] Da dong bo ' + CAST(@@ROWCOUNT AS NVARCHAR(10)) + N' so tap chi xuat ban lich su.';
GO

