-- 5. BAI BAO KHOA HOC (230 BAI BAO DA XUAT BAN)
-- -------------------------------------------------------------------------
IF OBJECT_ID('tempdb..#TmpBaiBao') IS NOT NULL DROP TABLE #TmpBaiBao;
CREATE TABLE #TmpBaiBao (
  [MaBaiBao] INT,
  [TieuDe] NVARCHAR(MAX),
  [TieuDeTiengAnh] NVARCHAR(MAX),
  [TomTat] NVARCHAR(MAX),
  [TomTatTiengAnh] NVARCHAR(MAX),
  [TuKhoa] NVARCHAR(MAX),
  [TrangThai] NVARCHAR(MAX),
  [MaDOI] NVARCHAR(MAX),
  [NgayGui] DATETIME,
  [NgayCapNhat] DATETIME,
  [MaNguoiDung] INT,
  [MaChuyenNganh] INT,
  [MaSoTapChi] INT,
  [TrangBatDau] INT,
  [TrangKetThuc] INT
);

SET IDENTITY_INSERT BaiBao ON;
SELECT [MaBaiBao], [TieuDe], [TieuDeTiengAnh], [TomTat], [TomTatTiengAnh], [TuKhoa], [TrangThai], [MaDOI], [NgayGui], [NgayCapNhat], [MaNguoiDung], [MaChuyenNganh], [MaSoTapChi], [TrangBatDau], [TrangKetThuc] FROM #TmpBaiBao t
WHERE NOT EXISTS (SELECT 1 FROM BaiBao b WHERE b.MaBaiBao = t.MaBaiBao);
SET IDENTITY_INSERT BaiBao OFF;
DROP TABLE #TmpBaiBao;
PRINT N'  [OK] Da dong bo ' + CAST(@@ROWCOUNT AS NVARCHAR(10)) + N' bai bao khoa hoc da xuat ban.';
GO

